commands.command:
set -eu; export JAVA_HOME="$(/usr/libexec/java_home -v 21)"; test "$(git rev-parse HEAD)" = "0fe28cc50c0cb2aab19af31aaf4a40a76aff3205"; python3 - <<'PY'
from pathlib import Path
p=Path('feature/telemetry/src/main/java/io/blueeye/feature/telemetry/TelemetryBridgeScreen.kt')
s=p.read_text()
old='''        rememberLauncherForActivityResult(ActivityResultContracts.StartIntentSenderForResult()) { activityResult ->
            if (activityResult.resultCode != Activity.RESULT_OK || activityResult.data == null) {
                viewModel.onAuthorizationFailed("Google authorization was cancelled")
                return@rememberLauncherForActivityResult
            }
            try {
                consumeAuthorizationResult(
                    authorizationClient.getAuthorizationResultFromIntent(activityResult.data!!),
                )
            } catch (error: ApiException) {
                viewModel.onAuthorizationFailed(error.message ?: "Google authorization failed")
            }
        }
'''
new='''        rememberLauncherForActivityResult(ActivityResultContracts.StartIntentSenderForResult()) { activityResult ->
            val resultData = activityResult.data
            if (resultData == null) {
                val message =
                    if (activityResult.resultCode == Activity.RESULT_CANCELED) {
                        "Google authorization was cancelled"
                    } else {
                        "Google authorization returned no result"
                    }
                viewModel.onAuthorizationFailed(message)
                return@rememberLauncherForActivityResult
            }
            try {
                consumeAuthorizationResult(
                    authorizationClient.getAuthorizationResultFromIntent(resultData),
                )
            } catch (error: ApiException) {
                viewModel.onAuthorizationFailed(error.message ?: "Google authorization failed")
            }
        }
'''
assert old in s, 'expected authorization launcher block not found'
p.write_text(s.replace(old,new,1))
PY
./gradlew :feature:telemetry:compileDebugKotlin :feature:telemetry:ktlintCheck :feature:telemetry:detekt :app:compileDebugKotlin --stacktrace; git diff --check; git diff -- feature/telemetry/src/main/java/io/blueeye/feature/telemetry/TelemetryBridgeScreen.kt; git add feature/telemetry/src/main/java/io/blueeye/feature/telemetry/TelemetryBridgeScreen.kt; git commit -m 'fix: parse Google authorization result'; git rev-parse HEAD
